 void Arrange(){if(arranging||layoutRoot==null||layoutHeading==null||layoutSensors==null)return;arranging=true;try{layoutRoot.SuspendLayout();int available=Math.Max(250,layoutRoot.ClientSize.Width-layoutRoot.Padding.Horizontal-SystemInformation.VerticalScrollBarWidth-4);foreach(Control c in layoutRoot.Controls){int width=Math.Max(1,available-c.Margin.Horizontal);if(c is FlowLayoutPanel){c.MinimumSize=new Size(width,0);c.MaximumSize=new Size(width,0);c.Width=width;}else if(c is Label){c.MaximumSize=new Size(width,0);}else c.Width=width;}
 bool narrow=available<480;int columns=narrow?1:2;if(sensorColumns!=columns){sensorColumns=columns;layoutSensors.SuspendLayout();layoutSensors.ColumnCount=columns;layoutSensors.RowCount=narrow?4:2;layoutSensors.ColumnStyles.Clear();layoutSensors.RowStyles.Clear();for(int x=0;x<columns;x++)layoutSensors.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,100f/columns));for(int y=0;y<layoutSensors.RowCount;y++)layoutSensors.RowStyles.Add(new RowStyle(SizeType.Percent,100f/layoutSensors.RowCount));layoutSensors.SetCellPosition(fan1,new TableLayoutPanelCellPosition(0,0));layoutSensors.SetCellPosition(fan2,new TableLayoutPanelCellPosition(narrow?0:1,narrow?1:0));layoutSensors.SetCellPosition(cpu,new TableLayoutPanelCellPosition(0,narrow?2:1));layoutSensors.SetCellPosition(gpu,new TableLayoutPanelCellPosition(narrow?0:1,narrow?3:1));layoutSensors.Height=narrow?304:160;layoutSensors.ResumeLayout();layoutHeading.SuspendLayout();layoutHeading.ColumnCount=columns;layoutHeading.RowCount=narrow?2:1;layoutHeading.ColumnStyles.Clear();layoutHeading.RowStyles.Clear();layoutHeading.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,100));if(!narrow)layoutHeading.ColumnStyles.Add(new ColumnStyle(SizeType.Absolute,124));if(narrow){layoutHeading.RowStyles.Add(new RowStyle(SizeType.Absolute,42));layoutHeading.RowStyles.Add(new RowStyle(SizeType.Absolute,42));}else layoutHeading.RowStyles.Add(new RowStyle(SizeType.Percent,100));layoutHeading.SetCellPosition(headingTitle,new TableLayoutPanelCellPosition(0,0));layoutHeading.SetCellPosition(headingLogo,new TableLayoutPanelCellPosition(narrow?0:1,narrow?1:0));headingLogo.Anchor=narrow?AnchorStyles.Left:AnchorStyles.Right;layoutHeading.Height=narrow?86:50;layoutHeading.ResumeLayout();}
