 void EnsureStartup(CoolingSnapshot state){if(state.Startup!="ON"){startupLinkStamp=0;return;}string link=Path.Combine(Paths.Info().Startup,StartupIntegration.Shortcut);if(!File.Exists(link))return;long stamp=File.GetLastWriteTimeUtc(link).Ticks;if(stamp==startupLinkStamp)return;Type t=Type.GetTypeFromProgID("WScript.Shell",true);object shell=Activator.CreateInstance(t),shortcut=null;try{shortcut=t.InvokeMember("CreateShortcut",System.Reflection.BindingFlags.InvokeMethod,null,shell,new object[]{link});string target=Convert.ToString(shortcut.GetType().InvokeMember("TargetPath",System.Reflection.BindingFlags.GetProperty,null,shortcut,null));if(String.Equals(target,typeof(NativeWindow).Assembly.Location,StringComparison.OrdinalIgnoreCase)){startupLinkStamp=stamp;return;}if(target.StartsWith(Paths.Root+Path.DirectorySeparatorChar,StringComparison.OrdinalIgnoreCase))StartupIntegration.CreateShortcut(typeof(NativeWindow).Assembly.Location,link,"--tray");startupLinkStamp=File.GetLastWriteTimeUtc(link).Ticks;}finally{if(shortcut!=null)System.Runtime.InteropServices.Marshal.FinalReleaseComObject(shortcut);System.Runtime.InteropServices.Marshal.FinalReleaseComObject(shell);}}
