 static void Prepare(Button b,string text,Func<Task> action){b.Text=text;b.AutoSize=true;b.Padding=new Padding(8,5,8,5);b.BackColor=Color.FromArgb(42,60,83);b.ForeColor=Color.White;b.FlatStyle=FlatStyle.Flat;b.Margin=new Padding(0,0,9,5);if(action!=null)b.Click+=async delegate{await action();};}
