 async void RefreshStatus(){if(refreshing||IsDisposed)return;refreshing=true;try{var prior=Task.Run(()=>PipeClient.Send("status"));var fresh=Task.Run(()=>CoolingClient.Send("status"));await Task.WhenAll(prior,fresh);if(IsDisposed)return;Reply a=prior.Result;CoolingReply b=fresh.Result;if(!a.Ok||!b.Ok)throw new IOException(a.Error??b.Error);Display(a.Snapshot,b.Snapshot);if(resume&&b.Snapshot.CanControl){resume=false;await Old("resume");await Cooling("resume");}}catch(Exception e){if(!IsDisposed){detail.Text="Mesures indisponibles · "+e.Message;fan1.Text="Ventilateur 1\n— tr/min";fan2.Text="Ventilateur 2\n— tr/min";low.Enabled=high.Enabled=zero.Enabled=false;}}finally{refreshing=false;}}
 void Display(Snapshot prior,CoolingSnapshot s){current=s;EnsureStartup(s);DateTime t;bool fresh=DateTime.TryParse(s.FanUTC,null,System.Globalization.DateTimeStyles.RoundtripKind,out t)&&(DateTime.UtcNow-t.ToUniversalTime()).TotalSeconds<=6;fan1.Text="Ventilateur 1\n"+(fresh&&s.Fan1.HasValue?s.Fan1.Value.ToString("N0"):"—")+" tr/min";fan2.Text="Ventilateur 2\n"+(fresh&&s.Fan2.HasValue?s.Fan2.Value.ToString("N0"):"—")+" tr/min";cpu.Text="CPU Package\n"+Temperature(prior,"CpuPackage");gpu.Text="GPU NVIDIA\n"+Temperature(prior,"GpuTemperature");detail.Text="Ventilation : "+ModeName(s.Actual)+" · "+s.State+"\n"+s.Detail;power.Text="Performances · Secteur : "+ModeName(prior.PerformanceAc)+" / Batterie : "+ModeName(prior.PerformanceDc)+" · "+(prior.Source=="AC"?"Secteur":"Batterie");low.Enabled=high.Enabled=s.CanControl;zero.Enabled=s.CanZero;zero.Text=s.ZeroActive?"0 dB : ON":"0 dB";startup.Text="Démarrage : "+s.Startup;}
 static string ModeName(string s){return s=="Eco"?"Éco":s=="Renforce"?"Renforcé":s=="Zero"?"0 dB":s;}
 static string Temperature(Snapshot s,string key){SensorValue v;DateTime t;if(!s.Sensors.TryGetValue(key,out v)||!v.Value.HasValue||v.Status!="valid"||!DateTime.TryParse(v.AcquiredUtc,out t)||(DateTime.UtcNow-t.ToUniversalTime()).TotalSeconds>6)return "— °C";return v.Value.Value.ToString("F1")+" °C";}
 async Task SaveAll(){if(current!=null&&current.ZeroActive){await Cooling("save");feedback.Text="Demande 0 dB enregistrée ; profils précédents conservés.";return;}bool windowsSaved=false;try{Reply a=await Task.Run(()=>PipeClient.Send("save"));if(!a.Ok)throw new IOException(a.Error);windowsSaved=true;CoolingReply b=await Task.Run(()=>CoolingClient.Send("save"));if(!b.Ok)throw new IOException(b.Error);feedback.Text="Profils Windows et ventilation enregistrés et relus.";}catch(Exception e){feedback.Text=(windowsSaved?"Profils Windows enregistrés ; ventilation non confirmée · ":"Enregistrement non confirmé · ")+e.Message;}}
 async Task Old(string command,string value=null){try{if(command=="performance"&&current!=null&&current.ZeroActive){CoolingReply off=await Task.Run(()=>CoolingClient.Send("set","Auto"));if(!off.Ok)throw new IOException(off.Error);for(int i=0;i<40;i++){await Task.Delay(100);off=await Task.Run(()=>CoolingClient.Send("status"));if(off.Ok&&!off.Snapshot.ZeroActive)break;}if(off.Snapshot.ZeroActive)throw new IOException("Restitution CPU encore en cours");}Reply r=await Task.Run(()=>PipeClient.Send(command,value));if(!r.Ok)throw new IOException(r.Error);if(!IsDisposed)feedback.Text=command=="save"?"Profils Windows enregistrés et relus.":command=="resume"?"Profils enregistrés repris.":"Profil confirmé par Windows.";}catch(Exception e){if(!IsDisposed)feedback.Text="Action non confirmée · "+e.Message;}}
 async Task Cooling(string command,string value=null){try{CoolingReply r=await Task.Run(()=>CoolingClient.Send(command,value));if(!r.Ok)throw new IOException(r.Error);if(!IsDisposed)feedback.Text=command=="save"?"Réglages de ventilation enregistrés et relus.":command=="startup"?"Démarrage vérifié : "+r.Snapshot.Startup:command=="resume"?"Demande enregistrée reprise sous surveillance.":"Demande "+ModeName(value)+" reçue ; confirmation par les mesures en cours.";}catch(Exception e){if(!IsDisposed)feedback.Text="Action non confirmée · "+e.Message;}RefreshStatus();}
 async Task Quit(){if(quitPending)return;quitPending=true;try{CoolingReply r=await Task.Run(()=>CoolingClient.Send("set","Auto"));if(!r.Ok)throw new IOException(r.Error);bool automatic=false;for(int i=0;i<30;i++){r=await Task.Run(()=>CoolingClient.Send("status"));if(r.Ok&&r.Snapshot.Actual=="Auto"&&!r.Snapshot.Pending){automatic=true;break;}await Task.Delay(200);}if(!automatic)throw new IOException("Retour Auto encore non confirmé");quitting=true;Close();}catch(Exception e){feedback.Text="Restitution Auto non confirmée · "+e.Message;}finally{quitPending=false;}}
