internal static class NativeUiMain {
 [STAThread]public static int Main(string[] args){if(Paths.Info().OwnerSid!=WindowsIdentity.GetCurrent().User.Value)return 77;string key="Local\\ThinkPadModes.NativeUI."+WindowsIdentity.GetCurrent().User.Value;bool first;using(var mutex=new Mutex(true,key,out first))using(var open=new EventWaitHandle(false,EventResetMode.AutoReset,key+".Open")){if(!first){open.Set();return 0;}try{try{if(CoolingNative.Pid()==0)CoolingNative.Start();}catch{CoolingNative.Start();}Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);Application.Run(new NativeWindow(Array.IndexOf(args,"--tray")>=0,Array.IndexOf(args,"--no-resume")<0,open));return 0;}finally{mutex.ReleaseMutex();}}}
